"""Offline report generation from read-only metadata and isolated compatibility tests."""
import csv,hashlib,json,sys,xml.etree.ElementTree as ET
from pathlib import Path
r=Path(Path('/tmp/nectec-readiness-path.txt').read_text().strip());rem=Path('/home/lailai/ollama-test/security_remediation/remediation-20261104T111222Z-e4089eae')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def js(name,obj):(r/name).write_text(json.dumps(obj,indent=2)+'\n')
def text(name,value):(r/name).write_text(value)
def csvwrite(name,rows):
 with (r/name).open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
assert not (r/'reports/FINAL_DEPLOYMENT_READINESS.md').exists()
runtime=json.loads((r/'evidence/runtime.json').read_text());ports=runtime['ports'];old={(x['method'],x['path']):x for x in ports['8001']['operations']};new={(x['method'],x['path']):x for x in ports['8002']['operations']};rows=[]
for method,path in sorted(set(old)|set(new)):
 a=old.get((method,path));b=new.get((method,path));rows.append({'method':method,'path':path,'8001_present':a is not None,'8002_present':b is not None,'8001_parameters':json.dumps(a['parameters']) if a else '', '8002_parameters':json.dumps(b['parameters']) if b else '', 'difference':'new operation' if a is None else 'parameter/dependency metadata changed' if a['parameters']!=b['parameters'] else 'same advertised parameter metadata','sensitive_scope':'job submission/control or user administration' if method in ['POST','PATCH','DELETE'] and path!='/auth/login' and path!='/auth/logout' else 'private output/job metadata' if path.startswith('/jobs') else 'authentication/cluster/UI metadata','limitation':'Metadata only; no unauthorized/private operation invoked'})
csvwrite('reports/portal_route_comparison.csv',rows)
onlynew=[f'{m} {p}' for m,p in sorted(set(new)-set(old))];common_changed=[f'{m} {p}' for m,p in sorted(set(old)&set(new)) if old[(m,p)]['parameters']!=new[(m,p)]['parameters']]
js('reports/portal_route_summary.json',{'8001_operations':len(old),'8002_operations':len(new),'new_operations_8002':onlynew,'common_operations_changed_parameter_metadata':common_changed,'schema_changes':list(json.loads((r/'evidence/schema-differences.json').read_text())),'exact_loaded_legacy_source_revision':'not recoverable from nonintrusive metadata; do not label a Git commit as verified runtime code'})
summary=[];cases=[];observed={}
for suite,n in [('portal',108),('chat',77),('postgres',11),('chat-forwarding',2)]:
 cmd=json.loads((r/'raw'/f'{suite}-1-command.json').read_text());tree=ET.parse(r/'raw'/f'{suite}-1.xml');tests=tree.findall('.//testcase');assert cmd['exit_code']==0 and len(tests)==n
 failures=len(tree.findall('.//failure'));errors=len(tree.findall('.//error'));skips=len(tree.findall('.//skipped'));assert not (failures or errors or skips)
 log=(r/'raw'/f'{suite}-1.log').read_text();meta=json.loads(next(x[len('STAGING_ENVIRONMENT='):] for x in log.splitlines() if x.startswith('STAGING_ENVIRONMENT=')));observed[suite]=meta
 expected=json.loads((r/'evidence'/f'{cmd["runtime_profile"]}-runtime-packages.json').read_text());assert all(meta['packages'].get(k)==v for k,v in expected['packages'].items())
 if suite!='postgres':assert meta['python']==expected['python']
 environment='copied portal packages and exact host Python' if suite=='portal' else 'host Python 3.10.12 with copied deployed chat client packages, disposable PostgreSQL14' if suite=='postgres' else 'new networkless/read-only container from deployed image, exact Python3.10.21'
 summary.append({'suite':suite,'passed':n,'failed':failures,'errors':errors,'skipped':skips,'exit_code':cmd['exit_code'],'environment':environment,'runtime_versions_match':True,'python_patch_matches':suite!='postgres','evidence':f'raw/{suite}-1.xml'})
 for t in tests:cases.append({'suite':suite,'test':t.get('name'),'classname':t.get('classname'),'status':'passed','seconds':t.get('time')})
assert len(cases)==198;csvwrite('reports/compatibility_results.csv',summary);csvwrite('reports/test_cases.csv',cases);js('reports/observed_test_environments.json',observed)
previous=json.loads((rem/'reports/test_environment.json').read_text());portal=json.loads((r/'evidence/portal-runtime-packages.json').read_text());chat=json.loads((r/'evidence/chat-runtime-packages.json').read_text());deps=[]
for name in ['fastapi','starlette','pydantic','uvicorn','argon2-cffi','psycopg','python-dotenv','anyio']:
 deps.append({'package':name,'prior_remediation_tests':previous.get(name,'not recorded in prior summary'),'portal_installed':portal['packages'].get(name,'not installed'),'chat_deployed_image':chat['packages'].get(name,'not installed'),'current_portal_stage':observed['portal']['packages'].get(name,'not installed'),'current_chat_stage':observed['chat']['packages'].get(name,'not installed')})
csvwrite('reports/dependency_comparison.csv',deps)
cloud=json.loads((r/'evidence/cloudflare-current-routing.json').read_text());cfg=cloud['endpoints']['/config'];diag=cloud['endpoints']['/diag/tunnel'];assert cfg['status']==200 and diag['status']==200
assert len(cfg['ingress'])==2 and cfg['ingress'][0]['service']=='ssh://localhost:22' and cfg['ingress'][1]['service']=='http_status:404'
# Source/config and all earlier immutable evidence remain untouched.
before=json.loads((r/'evidence/preservation_before.json').read_text());changed=[name for name,h in before.items() if not Path(name).is_file() or sha(Path(name))!=h]
append_only=[]
for name in changed:
 assert name=='/home/lailai/slurm-portal/logs/uvicorn-8002.log', changed
 data=Path(name).read_bytes();digest=hashlib.sha256();length=0;found=None
 for line in data.splitlines(keepends=True):
  digest.update(line);length+=len(line)
  if digest.hexdigest()==before[name]:found=length;break
 assert found is not None,'historical access-log bytes changed, not append-only'
 tail=data[found:];assert all(b'GET /openapi.json HTTP/' in line and b'200 OK' in line for line in tail.splitlines()),'unexplained access-log append'
 append_only.append({'path':name,'original_prefix_sha256':before[name],'original_prefix_bytes':found,'new_bytes':len(tail),'new_lines':len(tail.splitlines()),'reason':'normal access logging of read-only OpenAPI metadata request'})
js('reports/preservation.json',{'original_source_and_sealed_evidence_unchanged':True,'protected_files_n':len(before),'byte_identical_files_n':len(before)-len(changed),'append_only_runtime_logs':append_only,'unexpected_changes':[],'scope':'Original project/source, databases as byte-hash preservation only, prior sealed LLM/MPS/security/remediation evidence; no production SQL queries; dependency environments/Git/caches excluded'})
for row in json.loads((rem/'reports/changed_application_files.json').read_text()):assert sha(Path(row['original_path']))==row['original_sha256'] and sha(r/'staging'/row['isolated_path'])==row['remediated_sha256']
post=json.loads((r/'evidence/post-validation-deployment.json').read_text());assert post['container_and_image_unchanged'] and post['production_container_filesystem_unchanged'] and not post['ephemeral_test_containers_remaining']
text('reports/FINAL_DEPLOYMENT_READINESS.md',f'''# NECTEC final deployment-readiness assessment\n\n## Decision\n\n**Compatibility gate passed. Deployment remains pending separate operator authorization and portal cutover decisions.** The reviewed fixes were applied only to isolated staging copies; no production source, environment, image, container, account or service was changed. Assessment time: {runtime['date']}. The directory timestamp uses UTC; local Bangkok date is 5 November 2026.\n\n## Portal runtime inventory and intended use\n\nPort 8001 is slurm-portal.service (PID3148336), launched 8 October from /home/lailai/slurm-portal with that directory's .venv Python/Uvicorn. Port 8002 is a separate Uvicorn process (PID2019096), launched 28 October from the same directory. Neither command uses reload. They advertise the same API title/version0.2.0, which is insufficient to identify the loaded implementation.\n\nRead-only OpenAPI capture found {len(old)} operations on 8001 and {len(new)} on 8002. The newer instance adds: {', '.join(onlynew)}. Its common private job/cluster operations advertise session-cookie parameters; mutation paths additionally advertise the portal CSRF header. The legacy document lacks those parameters and authentication/admin routes. Request schemas common to both, including JobRequest, match; only LoginRequest, CreateResearcherRequest and UpdateResearcherStatusRequest are additional. portal_route_comparison.csv records every operation and parameter difference.\n\nBoth documents advertise potentially sensitive job submission, cancellation, requeue and output retrieval. This inventory does not establish unauthorized execution: no private/job endpoint was probed, and absent OpenAPI authentication metadata is not itself proof of bypass. The exact in-memory 8001 source revision cannot be recovered through this nonintrusive review. The earliest recorded Git commits are from21October, later than its process start. Current on-disk files cannot be substituted for proof of its loaded code.\n\nOperational intent is split. The installed systemd unit designates8001. The newer multi-user tests predominantly target8002, historical8002 logs contain2,881 HTTP request records, and note.coffee:36 documents `ssh -N -L 18002:127.0.0.1:8002 lai512`. Logs do not identify principals or distinguish researcher activity from tests; they support use history, not proof of current real-user activity or public ingress.\n\n**Recommendation:** use the multi-user implementation currently represented by8002 as the functional baseline, and converge on one operator-managed canonical service. The minimal management option is to promote the reviewed current source plus fixes under the existing systemd service on8001, then deliberately migrate the documented SSH-forward target and retire8002 only after confirming its consumers. If preserving port8002 is required, the operator may instead approve a managed-service port change. Neither port choice nor retirement is performed here.\n\nRestarting8001 activates current authentication, administrator/researcher rules, onboarding, ownership filtering and CSRF behavior accumulated since its legacy process started. It is therefore a broader application upgrade, not merely a reload of the three security findings. A simple source rollback would restore prepatch on-disk multi-user code, not necessarily recreate the unknown legacy in-memory implementation. Operator approval must explicitly cover this scope and rollback limitation.\n\n## Cloudflare routing: resolved for the running connector\n\nA safe read-only local metadata route was available despite the absent journal/config files. The cloudflared metrics listener's GET/config reports loaded configuration version{cfg['version']}; GET/diag/tunnel identifies tunnel `{diag['tunnelID']}` and connector `{diag['connectorID']}` with{diag['connections_n']} connections. Cloudflared version: {cloud['cloudflared_version']}. No connector token, API credential, cookie, private key or credential file content was read/printed.\n\nThe active rules are:\n\n| Hostname | Service |\n|---|---|\n| {cfg['ingress'][0]['hostname']} | ssh://localhost:22 |\n| Catch-all | http_status:404 |\n\n**This connector publishes SSH only. It has no direct HTTP route to8000,8001 or8002.** Global and per-route httpHostHeader are empty, with no origin hostname override. The documented localhost SSH forward is consistent with web access through SSH rather than a public HTTP tunnel rule. No public browser hostname for portal/chat was verified. Other connectors, gateways or account-wide Access policies were not audited, so this does not prove global absence of exposure.\n\nFor authoritative dashboard confirmation, the authorized operator should open Cloudflare dashboard → Networking → Tunnels → select the tunnel UUID above → Routes → Published application (older Zero Trust UI: Networks → Connectors → tunnel → Published Application Routes/Public Hostnames). Inspect each hostname/path rule's **Service Type/URL**, **HTTP Host Header**, and relevant origin settings. It should show the SSH rule and404 fallback. If another public browser URL is actually used, inspect its own tunnel/route and corresponding Access application policy; do not add or change a route merely to complete this assessment. [Cloudflare routing documentation](https://developers.cloudflare.com/tunnel/concepts/routing/), [dashboard setup](https://developers.cloudflare.com/tunnel/get-started/).\n\n## Production-compatible staging\n\nPortal staging used a new Python3.10.12 environment containing copies of all24 installed portal package versions. Chat's main and forwarded-origin tests ran in NEW disposable containers from the deployed immutable image, using the same Python3.10.21 and all30 runtime package versions. Containers had network=none, read-only filesystem/source mounts, no GPU devices, dropped capabilities and no production environment/database mount. Only temporary memory/files and new test-output storage were writable. Production images were neither rebuilt nor modified.\n\nTest-only pytest/httpx support packages were copied offline into separate staging locations; existing runtime versions were not replaced. No network download/pip upgrade was used. The exact reviewed patches were applied to staging base copies, and edited hashes match the sealed remediation package.\n\n| Suite | Passed | Failed/errors/skipped |\n|---|---:|---:|\n| Portal |108|0/0/0|\n| Chat authentication/ownership/origin |77|0/0/0|\n| Local-forward Host/Origin compatibility |2|0/0/0|\n| Additional disposable PostgreSQL isolation |11|0/0/0|\n| Total |198|0/0/0|\n\nAll suite processes exited0. Exact commands, runtime assertions, raw output and JUnit are preserved. The PostgreSQL supplement used all deployed chat client-package versions on host Python3.10.12 with a new private PostgreSQL14 cluster; its interpreter patch level differs from production. The79 main chat/forwarding cases used the exact production Python3.10.21 inside the deployed image. These scopes must remain distinct. Deprecation warnings concern TestClient/httpx and AnyIO compatibility; no assertion failed. Browser automation, real SSH connectivity, deployed account logins and live Slurm authorization were not tested.\n\nInstalled versions now exercised include FastAPI0.141.1/Pydantic2.13.5 on both systems, Starlette1.7.0/Uvicorn0.54.0 for portal and Starlette1.6.0/Uvicorn0.53.0/psycopg3.3.5 for chat. These differ from prior remediation tests with FastAPI0.162.0/Pydantic2.14.2. Portal metadata describes installed packages that a restart will load; it cannot prove versions already imported by the old in-memory process.\n\n## Compatibility, sessions and remaining risks\n\nThe existing approved identity set remains lailai/mangkud/apple; bootstrap restrictions remain narrower. No production accounts were queried or changed. Confirm actual researcher needs before cutover; additional names require explicit policy/Linux/Slurm approval. No database migration or session-schema change is needed. Persisted sessions should survive if database locations, cookie names, hostname and settings remain stable, but this was not tested with live sessions.\n\nChat mutations without a matching Origin or Referer now return403, including headerless scripts. In-memory checks confirmed registration/session/logout for localhost:18000 and127.0.0.1:18000, with hostile Origin denied. They simulate the documented forwarding shape, not a real browser or SSH session. Cookie hostnames remain significant; ports do not provide browser-cookie isolation. If a public HTTPS proxy is introduced or discovered, verify its Host/scheme handling and trusted forwarding rather than trusting arbitrary X-Forwarded-Host. [Uvicorn settings](https://uvicorn.dev/settings/).\n\nChat's container has no source bind mount; changing host server.py cannot update its running code. Its selected deployed settings are SESSION_COOKIE_SECURE=false and TTL86400. Portal Secure defaults false in source; process initial environment does not establish every effective runtime setting. Changing cookie/TLS policy is a separately reviewed deployment choice. This task does not alter filesystem/GPU/MPS permissions, rate limiting, production DB privileges or other audit findings.\n\n## Minimal deployment sequence — NOT EXECUTED\n\n1. Obtain explicit approval for the canonical portal port, broader legacy8001 upgrade or retirement, client-forward changes, affected instance restarts, maintenance window and any production test-user/session writes. Confirm whether users actually use another browser gateway.\n2. Recheck original-source hashes and patch dry runs; back up the four source files and launch configuration privately. Retain the chat image ID and a rollback tag. Preserve existing DB locations/volume/environment; no migration or routine database restore is required.\n3. Drain active streams and portal mutations; wait for uncertain submissions to resolve without automatic retry. An empty connection/queue snapshot is not proof of absent sessions or exclusive use.\n4. Apply portal app.py/auth.py/slurm_identity.py and chat server.py only after approval. Do not copy staging databases, test tools, reports or entire source trees into production.\n5. Restart the operator-selected portal instances using their verified launch method. Managed8001 uses systemctl restart slurm-portal.service; standalone8002 needs an approved PID-verified procedure. Avoid broad process-kill commands. Keep the documented researcher path available until migration is confirmed.\n6. Prepare a uniquely tagged chat candidate from the retained deployed image plus patched server.py, preserving the now-tested dependency set. Recreate only Compose service app with an approved image override and --no-deps --no-build. Keep the DB container/volume unchanged. No production build/recreate/restart was performed here.\n7. Run the focused verification checklist, record evidence and monitor. Retire an extra portal instance only with explicit approval and confirmed consumer migration.\n\nSee DEPLOYMENT_CHECKLIST.md and ROLLBACK_CHECKLIST.md. Downtime is not measured; budget a maintenance window. API requests/streams can be interrupted; existing Slurm jobs should continue because scheduler daemons are untouched.\n\n## Conclusion\n\nThe dependency compatibility gate is closed by198 passing isolated cases, and this connector's SSH-only ingress is verified. Remaining deployment gates are operator selection/approval of the portal cutover and legacy upgrade, confirmation of actual client paths/settings, and separately authorized deployment/browser smoke tests. The fixes remain NOT DEPLOYED. All source and sealed evidence files are unchanged: {len(before)-len(changed)} protected files are byte-identical; one live access log appended only the read-only OpenAPI request, with its original prefix hash verified; the production chat container/image/start time and filesystem are unchanged, service PIDs are stable, and disposable test containers were removed.\n''')
text('reports/DEPLOYMENT_CHECKLIST.md','''# Approval and verification checklist — no deployment executed\n\n## Before any change\n\n- [ ] Operator selects the canonical portal endpoint and acknowledges that restarting legacy8001 loads broader authentication/ownership behavior.\n- [ ] Confirm consumers of8001/8002 and documented SSH18002→8002; coordinate any forwarding change.\n- [ ] Confirm this tunnel's SSH-only rule in dashboard if required; identify any separate browser gateway before applying HTTPS assumptions.\n- [ ] Approve maintenance/drain window, exact restart scope and production test-account/session writes separately.\n- [ ] Verify four original source hashes against the remediation package and dry-run both reviewed application patches.\n- [ ] Securely back up those source files and launch metadata; retain immutable chat image/rollback tag and unchanged DB volume/environment.\n- [ ] Record in-flight portal submissions and chat streams; do not retry uncertain submissions automatically.\n\n## Change after separate authorization\n\n- [ ] Apply only the four reviewed runtime-file changes; preserve unrelated Git edits.\n- [ ] Restart only the approved portal instances; do not blindly restart/retire either port.\n- [ ] Build a separate candidate image from the retained runtime image plus patched server.py, without resolving new dependencies.\n- [ ] Recreate only chat service app with --no-deps --no-build using the approved image override.\n- [ ] Preserve existing production databases, accounts, secrets, scheduler, GPU and tunnel settings.\n\n## Focused post-deployment checks\n\n- [ ] Verify expected PIDs/image/code hashes and current API metadata on the chosen endpoints.\n- [ ] Portal malformed login with a fresh synthetic password sentinel, missing username:422 and no sentinel in response or reviewed logs. No real credential is needed.\n- [ ] Use an explicitly authorized existing researcher/test account to verify login and owner-scoped metadata; do not submit a Slurm job. Account/session writes require approval.\n- [ ] Verify deployed common identity policy. If admin live negative onboarding is authorized, an unapproved synthetic name must be rejected before record creation. Do not create real researchers as a smoke test.\n- [ ] Chat hostile/missing Origin with no valid fallback:403. Matching-origin POST/logout without cookie:200 and no DB mutation. Matching-origin POST/chat without cookie:401 and no inference.\n- [ ] Through the actual SSH-forward/browser path, verify legitimate login/session/logout, then a denied hostile-origin request. Authenticated synthetic conversation deletion requires separate permission for its data writes; delete only that explicitly created test record.\n- [ ] Do not send a valid inference request as part of these checks.\n- [ ] Check session continuity and errors; do not infer browser behavior solely from TestClient.\n\nAny failed control or unexpected routing/identity result stops progression. Keep staging and production evidence clearly separated.\n''')
text('reports/ROLLBACK_CHECKLIST.md','''# Rollback checklist — proposed, not executed\n\n- Retain original hashes, current source-file backups, launch arguments, image ID and environment/volume references before the approved change. Backups containing operational configuration must be private and excluded from research/public artifacts.\n- Roll back portal patches by restoring the backed-up prepatch files and restarting only approved processes. This restores the prepatch ON-DISK multi-user application; it cannot promise recovery of8001's unknown legacy in-memory code. Explicitly approve that limitation before the broader upgrade.\n- Roll back chat by recreating service app with the retained immutable previous image and unchanged environment/database volume, using --no-deps --no-build. Keep the DB service running.\n- Do not restore a stale database/session snapshot for these schema-free application fixes; that can discard legitimate intervening work. Any database recovery is a separate operator procedure.\n- If client SSH forwards or service routing were deliberately changed, restore only the recorded approved mapping; no Cloudflare/DNS/Zero Trust change is implied by these patches.\n- Drain requests, verify code/image/API metadata, verify the authorized user access path and preserve logs after rollback. A rollback reintroduces the known application weaknesses; require operator risk acceptance and a follow-up window.\n- No rollback, restart, live account mutation or deployment has occurred during this assessment.\n''')
refs=[{'title':'Cloudflare metrics handler GET/config implementation','url':'https://raw.githubusercontent.com/cloudflare/cloudflared/master/metrics/metrics.go'},{'title':'Cloudflare diagnostic tunnel-state handler','url':'https://raw.githubusercontent.com/cloudflare/cloudflared/master/diagnostic/handlers.go'},{'title':'Cloudflare routing','url':'https://developers.cloudflare.com/tunnel/concepts/routing/'},{'title':'Cloudflare dashboard tunnel setup','url':'https://developers.cloudflare.com/tunnel/get-started/'},{'title':'Uvicorn settings','url':'https://uvicorn.dev/settings/'}];js('evidence/references.json',refs)
text('README.md','''# NECTEC final deployment-readiness assessment\n\nStart with reports/FINAL_DEPLOYMENT_READINESS.md. **Reviewed fixes are staged and tested, NOT deployed.**\n\nThe current cloudflared connector publishes SSH only, not a portal/chat HTTP route. The two portal runtimes advertise different authentication APIs despite sharing current on-disk source.198 isolated compatibility cases passed with zero failed/error/skipped cases; deployed runtime package versions were preserved.\n\n## Evidence\n\n- raw/openapi-8000/8001/8002.json: public route metadata only; no private operations were invoked.\n- evidence/runtime.json, portal-use-records.json, portal-historical-log-summary.json, portal-git-history.json: source/runtime/process intent and historical use evidence.\n- evidence/cloudflare-current-routing.json: sanitized loaded/config and/diag/tunnel metadata, version, SSH service and nonsecret UUIDs. No token/credential content was read. Earlier unsuccessful journal/metrics attempts remain as evidence.\n- evidence/*runtime-packages.json, *staging-packages.json and test-only-extras.json: exact version inventories and additive test-only packages. No production pip upgrade or image rebuild occurred.\n- raw/staging-patch-application.json: reviewed patches applied only to staging; resulting hashes match the sealed remediation.\n- raw/*-command.json, *.log, *.xml: exact commands, source hashes, environment assertions, exit codes and complete test output.\n- reports/compatibility_results.csv and test_cases.csv:198 completed passing cases, with PostgreSQL interpreter limitation explicit.\n- reports/portal_route_comparison.csv and portal_route_summary.json: exact operations/parameters/schema differences; not authorization-exploit results.\n- reports/dependency_comparison.csv: earlier tests versus deployed and current staged packages.\n- reports/DEPLOYMENT_CHECKLIST.md and ROLLBACK_CHECKLIST.md: operator approval, change, smoke and rollback procedures.\n- reports/preservation.json, evidence/post-validation-deployment.json, validation.json: unchanged originals/services/container and output consistency.\n\n## Staging isolation and reproduction\n\nThe staging/ tree contains isolated copies and one additional test of localhost-forward Origin/session behavior. envs/ and exports/ contain OFFLINE copies of installed packages, and test_extras/ contains only missing test support. They are local execution artifacts, not production installations. Chat tests used a new disposable container from the existing image, network=none, read-only sources/root, no GPU devices and no production secrets or DB mounts. PostgreSQL used only its own private temporary cluster and host Python3.10.12 with deployed client packages; the main chat79 cases used exact image Python3.10.21.\n\nExact commands and mount constraints are recorded in raw/. Helper scripts capture this assessment root through /tmp/nectec-readiness-path.txt; do not rerun capture/preparation against the sealed assessment. For reproduction use a NEW copy/root, update that pointer deliberately, choose unused --attempt labels and recheck mounted writable output paths. Test commands refuse existing command records. No helper authorizes deployment.\n\nCapture scripts and version/source inventories provide provenance; no private.env/database/tunnel-token contents were copied. Metadata includes internal hostnames/UUIDs and process/listener information and should be reviewed before public release. Historical copied reports are context, not current runtime results.\n\nFILES_SHA256.json seals publication/evidence/staging-source files; copied envs/, exports/ and test_extras/ are excluded from that output seal and identified separately by version inventories and origins. Prior sealed packages and original files remain unchanged. No remote Cloudflare management API, route/DNS/policy update, GPU workload or model inference occurred.\n''')
